import React, { useEffect, useRef, useState } from "react";
import { useLocation, useParams } from "react-router-dom";
import { Link } from "react-router-dom";
import { PATH } from "~/utils/constants";
import { BlogDetail, Tag } from "~/utils/models/blog.model";
import { formatDate } from "~/utils/helpers/format";
import BlogInfoSide from "~/components/blog-info-side/BlogInfoSide";
import Comment from "~/components/Comment/Comment";
import axios from "~/config/axios";
import toastOption from "~/utils/constants/toastOption";
import parse from "html-react-parser";
import { toast } from "react-toastify";
import BlogsSide from "~/pages/user/blog/blog-detail/blogs-side/BlogsSide";
import { getBlogDetailApi } from "~/apis/blog.api";

// comment được fetch sau
function BlogDetailPage() {
  const { idBlog } = useParams<{ idBlog: string }>();
  const [blogDetail, setBlogDetail] = useState<BlogDetail>();
  const { state } = useLocation();
  // const refBlog = useRef<HTMLDivElement>(null);
  useEffect(() => {
    console.log(state);

    // fetch blog
    (async function () {
      try {
        const { data } = await getBlogDetailApi(idBlog!);
        setBlogDetail(data.data);
      } catch (error: any) {
        toast.error(error.message, toastOption);
      }
    })();
  }, [idBlog]);
  return (
    <div className="flex gap-5 px-8 mt-4 w-full">
      {blogDetail && <BlogInfoSide blogDetail={blogDetail} />}
      <div className="flex-[2] max-w-xl -mt-4">
        <img src={blogDetail?.thumbnail} alt="" className="h-[320px] w-full object-cover mb-6" />
        <div className="flex justify-between items-center">
          <h2 className="capitalize text-[#404040] opacity-80 mb-2">
            <span className="uppercase">{blogDetail?.blogCateId.name}</span>
          </h2>
          <span className="text-gray-500 mb-4">
            {blogDetail?.createdAt && formatDate(blogDetail.createdAt)}
          </span>
        </div>
        <div className="mb-3">
          Tag:
          {blogDetail?.blogTagIds.map(tag => (
            <Link
              to={`${PATH.BLOG}`}
              key={tag._id}
              state={{ tag: [tag._id] }}
              className="text-sm text-inherit px-3 py-2 mr-3 rounded-sm underline hover:opacity-100 text-gray-800 opacity-80"
            >
              {tag.name}
            </Link>
          ))}
        </div>
        <h1 className="text-4xl max-w-full mb-2 text-justify">{blogDetail?.title}</h1>

        <hr />
        <div className="my-4">{blogDetail?.contentRaw && parse(`${blogDetail?.contentRaw}`)}</div>
        {/* blog tương tự */}
        {!blogDetail?.hideComment && <Comment idBlog={idBlog as string} />}
      </div>
      {blogDetail && <BlogsSide blogDetail={blogDetail} />}
    </div>
  );
}

export default BlogDetailPage;
